import "server-only";
import { cookies } from "next/headers";
import {
  DEFAULT_LOCALE,
  LOCALE_COOKIE_NAME,
  isValidLocale,
  type Locale,
} from "./config";
import type {
  AppDictionaries,
  Namespace,
  TranslateFn,
} from "./types";
import { formatMessage } from "./format";

// Dictionary loaders mapping
const loaders: {
  [L in Locale]: {
    [N in Namespace]: () => Promise<AppDictionaries[N]>;
  };
} = {
  bn: {
    common: () => import("./dictionaries/bn/common.json").then((m) => m.default),
    home: () => import("./dictionaries/bn/home.json").then((m) => m.default),
    about: () => import("./dictionaries/bn/about.json").then((m) => m.default),
    programs: () => import("./dictionaries/bn/programs.json").then((m) => m.default),
    volunteer: () => import("./dictionaries/bn/volunteer.json").then((m) => m.default),
    report: () => import("./dictionaries/bn/report.json").then((m) => m.default),
    helpCenter: () => import("./dictionaries/bn/helpCenter.json").then((m) => m.default),
  },
  en: {
    common: () => import("./dictionaries/en/common.json").then((m) => m.default),
    home: () => import("./dictionaries/en/home.json").then((m) => m.default),
    about: () => import("./dictionaries/en/about.json").then((m) => m.default),
    programs: () => import("./dictionaries/en/programs.json").then((m) => m.default),
    volunteer: () => import("./dictionaries/en/volunteer.json").then((m) => m.default),
    report: () => import("./dictionaries/en/report.json").then((m) => m.default),
    helpCenter: () => import("./dictionaries/en/helpCenter.json").then((m) => m.default),
  },
};

/**
 * Reads the active locale from server cookies (NEXT_LOCALE).
 * Falls back to DEFAULT_LOCALE ("bn").
 */
export async function getServerLocale(): Promise<Locale> {
  try {
    const cookieStore = await cookies();
    const cookieValue = cookieStore.get(LOCALE_COOKIE_NAME)?.value;
    if (isValidLocale(cookieValue)) {
      return cookieValue;
    }
  } catch {
    // Fall back gracefully during static prerendering or build-time evaluation
  }
  return DEFAULT_LOCALE;
}

/**
 * Loads a specific namespace dictionary for the given locale.
 */
export async function getDictionary<N extends Namespace>(
  namespace: N,
  locale?: Locale
): Promise<AppDictionaries[N]> {
  const targetLocale = locale ?? (await getServerLocale());
  const loader = loaders[targetLocale][namespace];
  return (await loader()) as AppDictionaries[N];
}

/**
 * Production-grade server-side translation helper for Server Components.
 *
 * Usage:
 *   const t = await getTranslations("home");
 *   <h1>{t("hero.title")}</h1>
 *   <p>{t("stats.districts", { count: 64 })}</p>
 */
export async function getTranslations<N extends Namespace>(
  namespace: N,
  overrideLocale?: Locale
): Promise<TranslateFn<N>> {
  const locale = overrideLocale ?? (await getServerLocale());
  const dict = await getDictionary(namespace, locale);

  return ((key, params) => {
    return formatMessage(dict as Record<string, unknown>, key, params);
  }) as TranslateFn<N>;
}
